  class FLV {
    constructor(videoId, url) {
      // addJs("https://open.ys7.com/assets/ezuikit_v3.4/js/flv.min.js", () => {
      // console.log("加载flv.min.js成功", window.flvjs);
      console.log("isSupportFlv", window.flvjs.isSupported());
      if (window.flvjs.isSupported()) {
        this.initFLV(videoId, url);
      }
      // })
    }

    toString() {
      return `Flv ${this.coreX}-${this.coreY}`;
    }
    initFLV(videoId, flvUrl) {
      const {
        deviceSerial,
        channelNo,
        hd,
        type
      } = matchUrl(flvUrl);
      window.ezuikitMonitor.report({
        protocol: 'flv',
        url: flvUrl,
        serial: deviceSerial,
        no: channelNo,
        action: 1,
        logInfo: {
          type: type
        }
      });
      var video = document.getElementById(videoId);
      var hasControls = video.getAttribute('controls');
      if (!hasControls) {
        video.setAttribute('controls', true);
      }
      var flvPlayer = window.flvjs.createPlayer({
        type: 'flv',
        url: flvUrl,
        isLive: true
      }, {
        enableStashBuffer: true,
        stashInitialSize: 128,
        enableWorker: true
      });
      flvPlayer.attachMediaElement(video);
      flvPlayer.load();
      flvPlayer.play();
      this.flvUrl = flvUrl;
      this.flv = flvPlayer;
      this.video = video;
      this.video.addEventListener('oncanplaythrough', function () {
        console.log('oncanplaythrough');
      }, false);
      this.video.addEventListener('onerror', function () {
        console.log('onerror');
      }, false);
    }
    play() {
      console.log("执行flv播放", this.video);
      this.video.play();
    }
    stop() {
      // 通过暂停停止播放
      // this.video.pause();
      // this.video.src = "";
      this.video.pause();
      // 停止取流
      this.flv.unload();
      // this.hls.destroy();
    }

    destroy() {
      if (this.flv === undefined || this.flv === null) {
        return;
      }
      this.flv.pause();
      this.flv.unload();
      this.flv.detachMediaElement();
      this.flv.destroy();
      this.flv = null;
    }
  }

