  /**
   * console.error异常
   */
  class ConsoleError extends BaseMonitor {
    constructor(params) {
      super(params);
    }

    /**
     * 处理console事件
     */
    handleError() {
      this.registerInfo();
      this.registerWarn();
      this.registerError();
    }

    /**
     * 处理信息
     */
    registerInfo() {
      let t = this;
      console.tInfo = function () {
        t.handleLog(ErrorLevelEnum.INFO, ErrorCategoryEnum.CONSOLE_INFO, arguments);
      };
    }

    /**
     * 处理警告
     */
    registerWarn() {
      let t = this;
      console.tWarn = function () {
        t.handleLog(ErrorLevelEnum.WARN, ErrorCategoryEnum.CONSOLE_WARN, arguments);
      };
    }

    /**
     * 处理错误
     */
    registerError() {
      let t = this;
      console.tError = function () {
        t.handleLog(ErrorLevelEnum.ERROR, ErrorCategoryEnum.CONSOLE_ERROR, arguments);
      };
    }

    /**
     * 处理日志
     */
    handleLog(level, category, args) {
      try {
        this.level = level;
        let params = [...args];
        this.msg = params.join("\r\n"); //换行符分割
        this.url = location.href; //当前地址
        this.category = category;
        this.recordError();
      } catch (error) {
        console.log("console统计错误异常", level, error);
      }
    }
  }

  /**
   * 初始化console事件
   */
  (function () {
    //创建空console对象，避免JS报错  
    if (!window.console) {
      window.console = {};
    }
    let funcs = ['tInfo', 'tWarn', 'tError'];
    funcs.forEach((func, index) => {
      if (!console[func]) {
        console[func] = function () {};
      }
    });
  })();

  /**
   * 捕获JS错误
   */
  class JSError extends BaseMonitor {
    constructor(params) {
      super(params);
    }

    /**
     * 注册onerror事件
     */
    handleError() {
      window.onerror = (msg, url, line, col, error) => {
        console.log('monitor onerror');
        try {
          this.level = ErrorLevelEnum.WARN;
          this.category = ErrorCategoryEnum.JS_ERROR;
          this.msg = msg;
          this.url = url;
          this.line = line;
          this.col = col;
          this.errorObj = error;
          this.recordError();
        } catch (error) {
          console.log("js错误异常", error);
        }
      };
    }
  }

  /**
   * 捕获未处理的Promise异常
   */
  class PromiseError extends BaseMonitor {
    constructor(params) {
      super(params);
    }

    /**
     * 处理错误
     */
    handleError() {
      window.addEventListener('unhandledrejection', event => {
        try {
          if (!event || !event.reason) {
            return;
          }
          //判断当前被捕获的异常url，是否是异常处理url，防止死循环
          if (event.reason.config && event.reason.config.url) {
            this.url = event.reason.config.url;
          }
          this.level = ErrorLevelEnum.WARN;
          this.category = ErrorCategoryEnum.PROMISE_ERROR;
          this.msg = event.reason;
          this.recordError();
        } catch (error) {
          console.log(error);
        }
      }, true);
    }
  }

